package io.github.miklires.mauction;import java.time.Instant;import java.util.UUID;public record Listing(UUID id,UUID seller,String sellerName,byte[] item,double price,ListingState state,UUID buyer,Instant createdAt,Instant expiresAt){public Listing{if(price<=0||!Double.isFinite(price))throw new IllegalArgumentException("Price must be positive");item=item.clone();}public byte[]item(){return item.clone();}}
